/**
Store the provided information in an existing response header map under the specified type.
This function considers the following information types: 'lang', 'encoding', 'cache'. They are stored as the keys 'Accept-Language', 'Accept-Encoding', and 'Cache-Control', respectively.
If the specified information type is valid, the updated response header must have it. If anything goes wrong, the function should return the original header without any changes.

@param info_type The type of information to store in the header.
@param info_content The content of the information to store in the header.
@param header The existing response header map.

@return The updated response header map with the stored information.
*/
void store_info_in_header(const std::string &info_type, const std::string &info_content, std::map<std::string, std::string> &header) {
    std::map<std::string, std::string> original_header = header; // Keep a copy of the original header

    if (info_type == "lang") {
        // Basic validation for Accept-Language: allows language tags (e.g., en-US, fr)
        // and quality values (e.g., en;q=0.9)
        std::regex lang_regex(R"(^[a-z]{2}(-[A-Z]{2})?(;\s*q=\d+(\.\d+)?)*$)");
        if (std::regex_match(info_content, lang_regex)) {
            header["Accept-Language"] = info_content;
        } else {
            header = original_header; // Revert to original if validation fails
        }
    } else if (info_type == "encoding") {
        // Basic validation for Accept-Encoding: allows common encoding types
        // (e.g., gzip, deflate, br) and quality values.
        std::regex encoding_regex(R"(^(gzip|deflate|br)(;\s*q=\d+(\.\d+)?)*$)");
        if (std::regex_match(info_content, encoding_regex)) {
            header["Accept-Encoding"] = info_content;
        } else {
            header = original_header; // Revert to original if validation fails
        }
    } else if (info_type == "cache") {
        // Basic validation for Cache-Control: allows common directives.
        // This is a simplified regex and might need to be more comprehensive
        // depending on the exact requirements for Cache-Control directives.
        std::regex cache_regex(R"(^(public|private|no-cache|no-store|max-age=\d+|s-maxage=\d+|immutable|must-revalidate|proxy-revalidate|stale-while-revalidate=\d+|stale-if-error=\d+)(,\s*(public|private|no-cache|no-store|max-age=\d+|s-maxage=\d+|immutable|must-revalidate|proxy-revalidate|stale-while-revalidate=\d+|stale-if-error=\d+))*$)");
        if (std::regex_match(info_content, cache_regex)) {
            header["Cache-Control"] = info_content;
        } else {
            header = original_header; // Revert to original if validation fails
        }
    }
    // If info_type is not one of the recognized types, the header remains unchanged
    // because we only modify it if a valid type is found and content is validated.
    // If validation fails for a recognized type, we revert to the original header.
}
